long test_va_copy(char *fmt, ...) {
  va_list va, copy;
  va_start(va, fmt);
  va_copy(copy, va);
  int i = va_arg(va, int);
  long l = va_arg(copy, long);
  va_end(copy);
  va_end(va);
  return i + l;
}

